// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }
    function testFuzz_property(address logger, bool status) public {
        // The owner variable is never assigned in C, so it defaults to address(0);
        // only address(0) passes the onlyOwner modifier.
        vm.prank(address(0));
        c.setApprovedLogger(logger, status);
        assertTrue(c.approvedLoggers(logger) == status);
    }
}
